// src/components/UploadVideosModal.js
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useLocation, useNavigate } from "react-router-dom";
import axios from "axios";
import * as tus from "tus-js-client";
import api, { uploadApi } from "../api";
import "./UploadVideosModal.css";

const CREATE_TIMEOUT_MS = 20000;
const POLL_MS = 2500;
const DIRECT_UPLOAD_MIN_BYTES = 50 * 1024 * 1024; // 50MB

// UI update throttling (4/sec)
const PROGRESS_THROTTLE_MS = 250;

// Bunny Stream transcoding mode.
// Videos go to Bunny Stream (TUS) so Bunny handles transcoding/adaptive HLS.
// Bunny Storage / server upload helpers are kept below for non-stream fallback compatibility.
const USE_BUNNY_STREAM_UPLOAD = true;

function baseTitle(filename = "") {
  const dot = filename.lastIndexOf(".");
  return dot > 0 ? filename.slice(0, dot) : filename;
}

function slugFromName(name = "") {
  return String(name)
    .toLowerCase()
    .trim()
    .replace(/[^\w\d]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

function fmtBytes(bytes = 0) {
  const b = Number(bytes) || 0;
  if (b < 1024) return `${b} B`;
  const kb = b / 1024;
  if (kb < 1024) return `${kb.toFixed(1)} KB`;
  const mb = kb / 1024;
  if (mb < 1024) return `${mb.toFixed(1)} MB`;
  const gb = mb / 1024;
  return `${gb.toFixed(2)} GB`;
}

function fmtEta(seconds) {
  const s = Math.max(0, Math.floor(seconds || 0));
  if (!s) return "";
  const m = Math.floor(s / 60);
  const r = s % 60;
  if (m <= 0) return `${r}s`;
  if (m < 60) return `${m}m ${r}s`;
  const h = Math.floor(m / 60);
  const mm = m % 60;
  return `${h}h ${mm}m`;
}

function CloudIcon({ size = 26 }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      aria-hidden
      className="uvm-cloud"
    >
      <path
        d="M6 19a4 4 0 0 1-.6-7.96A6 6 0 0 1 17.9 9.2 4.5 4.5 0 0 1 18 18H8"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        opacity="0.9"
      />
      <path
        d="M12 12v7m0-7 2.5 2.5M12 12 9.5 14.5"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function shallowEqual(a, b) {
  if (a === b) return true;
  if (!a || !b) return false;
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) return false;
  for (const k of ak) {
    if (a[k] !== b[k]) return false;
  }
  return true;
}

export default function UploadVideosModal({
  open,
  onClose,
  onDone,
  categorySlug: initialCategorySlug,
}) {
  const inputRef = useRef(null);
  const navigate = useNavigate();
  const location = useLocation();
  const inStudio = location.pathname.startsWith("/studio");
  const editHrefFor = (id) =>
    inStudio ? `/studio/videos/${id}` : `/admin/content/videos/${id}`;

  // Per-upload tracking to throttle progress updates
  // tracker[id] = { lastUiTs, lastPct, lastEta, lastSpeed, lastLoaded, lastT }
  const progressTrackerRef = useRef(Object.create(null));
  const createLocksRef = useRef(Object.create(null));

  // -------- Category state --------
  const [categories, setCategories] = useState([]);
  const [categoriesLoading, setCategoriesLoading] = useState(false);
  const [categoriesError, setCategoriesError] = useState("");
  const [selectedCategoryId, setSelectedCategoryId] = useState(null);
  const [selectedCategorySlug, setSelectedCategorySlug] = useState("");
  const [newCategoryName, setNewCategoryName] = useState("");
  const [creatingCategory, setCreatingCategory] = useState(false);
  const [categoryInlineError, setCategoryInlineError] = useState("");

  // ✅ Hide "new category" UI by default; toggle with +/-.
  const [showNewCategory, setShowNewCategory] = useState(false);

  // -------- Defaults --------
  const [defaultVisibility, setDefaultVisibility] = useState("private"); // private | public

  const urlCategorySlug = useMemo(() => {
    const search = new URLSearchParams(location.search || "");
    const fromQuery =
      search.get("category") ||
      search.get("category_slug") ||
      search.get("cat") ||
      "";
    return fromQuery.trim() || "";
  }, [location.search]);

  // Utility: patch a single item efficiently (no full-array map unless needed)
  const patchItem = useCallback((id, updater) => {
    setItems((prev) => {
      const idx = prev.findIndex((x) => x.id === id);
      if (idx < 0) return prev;
      const cur = prev[idx];
      const next =
        typeof updater === "function" ? updater(cur) : { ...cur, ...updater };
      if (shallowEqual(cur, next)) return prev;
      const copy = prev.slice();
      copy[idx] = next;
      return copy;
    });
  }, []);

  // Load categories when modal opens
  useEffect(() => {
    if (!open) return;

    let cancelled = false;

    async function loadCategories() {
      setCategoriesLoading(true);
      setCategoriesError("");
      setCategoryInlineError("");

      try {
        const res = await api.get("/categories");
        const list = Array.isArray(res?.data) ? res.data : [];
        if (cancelled) return;

        setCategories(list);

        // reset selection
        setSelectedCategoryId(null);
        setSelectedCategorySlug("");

        // ✅ Priority for auto-select:
        // 1) initialCategorySlug prop
        // 2) URL query (?category=)
        // 3) default to "Archives" if present
        const desiredSlug = (
          initialCategorySlug ||
          urlCategorySlug ||
          ""
        ).trim();

        let match = null;

        if (desiredSlug && list.length) {
          match =
            list.find(
              (c) =>
                c.slug === desiredSlug ||
                slugFromName(c.name) === desiredSlug ||
                String(c.id) === String(desiredSlug),
            ) || null;
        }

        if (!match && list.length) {
          // ✅ Default category: Archives
          match =
            list.find(
              (c) =>
                String(c?.name || "")
                  .trim()
                  .toLowerCase() === "archives",
            ) || null;
        }

        if (match) {
          setSelectedCategoryId(match.id ?? null);
          setSelectedCategorySlug(match.slug || slugFromName(match.name || ""));
        }
      } catch (err) {
        if (!cancelled) {
          setCategoriesError(
            err?.response?.data?.message ||
              err?.message ||
              "Failed to load categories",
          );
        }
      } finally {
        if (!cancelled) setCategoriesLoading(false);
      }
    }

    loadCategories();
    return () => {
      cancelled = true;
    };
  }, [open, initialCategorySlug, urlCategorySlug]);

  const handleCategoryChange = (e) => {
    const value = e.target.value;
    setCategoryInlineError("");
    if (!value) {
      setSelectedCategoryId(null);
      setSelectedCategorySlug("");
      return;
    }
    const cat = categories.find((c) => String(c.id) === String(value));
    setSelectedCategoryId(cat?.id ?? null);
    setSelectedCategorySlug(cat?.slug || slugFromName(cat?.name || ""));
  };

  const handleCreateCategory = async (e) => {
    e?.preventDefault?.();
    const name = newCategoryName.trim();
    if (!name) return;

    setCreatingCategory(true);
    setCategoriesError("");
    setCategoryInlineError("");

    try {
      const res = await api.post("/categories", { name });
      const cat = res?.data || {};
      const slug = cat.slug || slugFromName(cat.name || name);

      setCategories((prev) => [...prev, cat]);
      setSelectedCategoryId(cat.id ?? null);
      setSelectedCategorySlug(slug);
      setNewCategoryName("");

      // optional: collapse after success
      setShowNewCategory(false);
    } catch (err) {
      setCategoriesError(
        err?.response?.data?.message ||
          err?.message ||
          "Failed to create category",
      );
    } finally {
      setCreatingCategory(false);
    }
  };

  const categoryIsValid = !!(selectedCategoryId || selectedCategorySlug);

  // -------- Upload state --------
  const [items, setItems] = useState([]);
  const [dragOver, setDragOver] = useState(false);

  // Cleanup controllers + tracking when modal closes/unmounts
  useEffect(() => {
    if (open) return;

    // Abort any in-flight uploads if modal is closed
    items.forEach((it) => {
      if (
        it?.controller &&
        (it.status === "uploading" || it.status === "creating")
      ) {
        try {
          it.controller.abort();
        } catch {}
      }
    });

    // Clear tracking
    progressTrackerRef.current = Object.create(null);
    createLocksRef.current = Object.create(null);

    // Reset state
    setItems([]);
    setDragOver(false);
    setCategoryInlineError("");
    setDefaultVisibility("private");
    setShowNewCategory(false);
    setNewCategoryName("");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const pickFiles = () => {
    if (!categoryIsValid) {
      setCategoryInlineError(
        "Please select or create a category before uploading.",
      );
      return;
    }
    inputRef.current?.click();
  };

  const addFiles = useCallback(
    (fileList) => {
      const files = Array.from(fileList || []);
      if (!files.length) return;

      if (!categoryIsValid) {
        setCategoryInlineError(
          "Please select or create a category before uploading.",
        );
        return;
      }

      const now = Date.now();
      const entries = files.map((f) => ({
        id: `${f.name}-${f.size}-${now}-${Math.random()}`,
        file: f,
        sizeBytes: f.size || 0,
        progress: 0,
        status: "queued", // queued | uploading | creating | done | error | canceled
        error: "",
        controller: null,
        url: "",
        videoId: null,
        title: baseTitle(f.name || "Untitled"),
        durationSec: null,
        categoryId: selectedCategoryId ?? null,
        categorySlug: selectedCategorySlug || "uncategorized",
        createdAtMs: now,
        speedBps: 0,
        etaSec: null,
        processingStatus: null,
        visibility: defaultVisibility,
      }));

      setItems((prev) => [...prev, ...entries]);
      entries.forEach((entry) => startUpload(entry));
    },
    [
      categoryIsValid,
      selectedCategoryId,
      selectedCategorySlug,
      defaultVisibility,
    ],
  );

  function removeItem(id) {
    delete progressTrackerRef.current[id];
    setItems((prev) => prev.filter((x) => x.id !== id));
  }

  function cancelUpload(id) {
    const tracker = progressTrackerRef.current[id];
    if (tracker?.timer) {
      clearTimeout(tracker.timer);
      tracker.timer = null;
    }

    setItems((prev) => {
      const it = prev.find((x) => x.id === id);
      if (it?.controller) {
        try {
          it.controller.abort();
        } catch {}
      }
      const idx = prev.findIndex((x) => x.id === id);
      if (idx < 0) return prev;
      const cur = prev[idx];
      const next = { ...cur, status: "canceled", controller: null };
      if (shallowEqual(cur, next)) return prev;
      const copy = prev.slice();
      copy[idx] = next;
      return copy;
    });

    delete progressTrackerRef.current[id];
  }

  async function initDirectUpload({ file, kind, category }) {
    const payload = {
      filename: file?.name || "upload.bin",
      contentType: file?.type || "application/octet-stream",
      sizeBytes: file?.size || 0,
      kind: kind || "videos",
      category: category || "uncategorized",
    };

    const res = await api.post("/uploads/bunny/direct-init", payload);
    const d = res?.data || {};

    const uploadUrl = d.uploadUrl || d.upload_url || "";
    const publicUrl = d.publicUrl || d.public_url || "";
    const key = d.key || "";
    const ticket = d.ticket || "";
    const contentType = d.contentType || d.content_type || payload.contentType;

    if (!uploadUrl || !publicUrl || !ticket) {
      throw new Error("Direct init failed: missing uploadUrl/publicUrl/ticket");
    }

    return { uploadUrl, publicUrl, key, ticket, contentType };
  }

  async function mintDirectAccessKey({ ticket }) {
    const res = await api.post("/uploads/bunny/direct-auth", { ticket });
    const d = res?.data || {};
    const accessKey = d.accessKey || d.access_key || "";
    if (!accessKey) throw new Error("Direct auth failed: missing accessKey");
    return accessKey;
  }

  async function uploadDirectToBunny({
    uploadUrl,
    file,
    signal,
    onProgress,
    accessKey,
    contentType,
  }) {
    const headers = {
      "Content-Type": contentType || file?.type || "application/octet-stream",
      AccessKey: accessKey,
    };

    return axios.put(uploadUrl, file, {
      headers,
      signal,
      onUploadProgress: onProgress,
      timeout: 0,
      maxBodyLength: Infinity,
      maxContentLength: Infinity,
    });
  }

  async function createBunnyStreamPresign({ title, file }) {
    const res = await api.post("/bunny/stream/presign", {
      title: title || baseTitle(file?.name || "Untitled"),
      filename: file?.name || "upload.mp4",
      contentType: file?.type || "application/octet-stream",
      sizeBytes: file?.size || 0,
    });

    const d = res?.data || {};
    if (!d.ok || !d.videoId || !d.signature || !d.expires || !d.tusEndpoint) {
      throw new Error(d.message || "Bunny Stream presign failed");
    }

    return d;
  }

  function uploadFileToBunnyStream({ file, title, onProgress }) {
    let tusUpload = null;

    const task = new Promise(async (resolve, reject) => {
      try {
        const presign = await createBunnyStreamPresign({ title, file });

        tusUpload = new tus.Upload(file, {
          endpoint: presign.tusEndpoint,
          retryDelays: [0, 3000, 5000, 10000, 20000, 60000],
          headers: {
            AuthorizationSignature: String(presign.signature),
            AuthorizationExpire: String(presign.expires),
            VideoId: String(presign.videoId),
            LibraryId: String(presign.libraryId),
          },
          metadata: {
            filename: file?.name || "upload.mp4",
            filetype: file?.type || "application/octet-stream",
            title: title || baseTitle(file?.name || "Untitled"),
          },
          onError: reject,
          onProgress: (bytesUploaded, bytesTotal) => {
            onProgress?.({
              loaded: bytesUploaded,
              total: bytesTotal || file?.size || 0,
            });
          },
          onSuccess: () => {
            resolve({
              provider: "bunny_stream",
              provider_key: presign.videoId,
              bunny_video_id: presign.videoId,
              bunny_library_id: String(presign.libraryId || ""),
              video_url: presign.playbackUrl || presign.hlsUrl || "",
              playback_url: presign.playbackUrl || presign.hlsUrl || "",
              embed_url: presign.embedUrl || "",
              // Do not save Bunny Stream raw thumbnail URLs here.
              // They can fail if the Stream CDN blocks direct thumbnail access.
              // Admins can upload a custom thumbnail from Video Details instead.
              thumbnail_url: null,
              processing_status: "processing",
            });
          },
        });

        const previousUploads = await tusUpload.findPreviousUploads();
        if (previousUploads.length) {
          tusUpload.resumeFromPreviousUpload(previousUploads[0]);
        }

        tusUpload.start();
      } catch (e) {
        reject(e);
      }
    });

    return {
      promise: task,
      abort: () => {
        if (tusUpload) {
          try {
            tusUpload.abort(true);
          } catch {}
        }
      },
    };
  }

  async function uploadViaServer({ file, categorySlug, signal, onProgress }) {
    const fd = new FormData();
    fd.append("file", file);
    fd.append("kind", "videos");
    if (categorySlug) fd.append("category", categorySlug);

    return uploadApi.post("/uploads/video", fd, {
      signal,
      onUploadProgress: onProgress,
      timeout: 0,
      maxBodyLength: Infinity,
      maxContentLength: Infinity,
    });
  }

  function ensureTracker(id) {
    if (!progressTrackerRef.current[id]) {
      progressTrackerRef.current[id] = {
        lastUiTs: 0,
        lastPct: -1,
        lastEta: null,
        lastSpeed: 0,
        lastLoaded: 0,
        lastT: Date.now(),
        timer: null,
      };
    }
    return progressTrackerRef.current[id];
  }

  function cleanupTracker(id) {
    const t = progressTrackerRef.current[id];
    if (t?.timer) {
      clearTimeout(t.timer);
      t.timer = null;
    }
    delete progressTrackerRef.current[id];
  }

  function safeSetProgress(id, patch) {
    patchItem(id, (cur) => {
      if (!cur) return cur;
      return { ...cur, ...patch };
    });
  }

  async function startUpload(entry) {
    const { id, file, visibility } = entry;

    ensureTracker(id);
    safeSetProgress(id, { status: "uploading", error: "" });

    let streamInfo = null;

    const tracker = ensureTracker(id);

    const flushProgress = (patch) => {
      patchItem(id, (cur) => {
        if (!cur) return cur;

        const next = { ...cur, ...patch };

        if (["done", "error", "canceled"].includes(next.status)) {
          next.controller = null;
        }

        return next;
      });
    };

    const onProgress = (e) => {
      const total = Number(e?.total || file?.size || 0);
      const loaded = Number(e?.loaded || 0);
      if (!total) return;

      const pct = Math.max(
        0,
        Math.min(100, Math.round((loaded / total) * 100)),
      );

      const now = Date.now();
      const dt = Math.max(1, now - tracker.lastT);
      const dLoaded = Math.max(0, loaded - tracker.lastLoaded);
      const speed = Math.floor((dLoaded * 1000) / dt);
      const remain = Math.max(0, total - loaded);
      const eta = speed > 0 ? Math.round(remain / speed) : null;

      tracker.lastLoaded = loaded;
      tracker.lastT = now;

      const due = now - tracker.lastUiTs >= PROGRESS_THROTTLE_MS || pct >= 100;

      const pctChanged = pct !== tracker.lastPct;
      const etaChanged =
        (eta == null && tracker.lastEta != null) ||
        (eta != null && tracker.lastEta == null) ||
        (eta != null &&
          tracker.lastEta != null &&
          Math.abs(eta - tracker.lastEta) >= 1);

      const speedChanged = Math.abs(speed - (tracker.lastSpeed || 0)) >= 1024;

      if (!due || (!pctChanged && !etaChanged && !speedChanged && pct < 100))
        return;

      tracker.lastUiTs = now;
      tracker.lastPct = pct;
      tracker.lastEta = eta;
      tracker.lastSpeed = speed;

      flushProgress({
        progress: pct,
        status: pct >= 100 ? "creating" : "uploading",
        speedBps: speed,
        etaSec: eta,
      });
    };

    try {
      if (!USE_BUNNY_STREAM_UPLOAD) {
        throw new Error("Bunny Stream upload is disabled");
      }

      const bunnyTask = uploadFileToBunnyStream({
        file,
        title: entry.title,
        onProgress,
      });

      safeSetProgress(id, {
        controller: {
          abort: () => {
            try {
              bunnyTask.abort();
            } catch {}
          },
        },
      });

      streamInfo = await bunnyTask.promise;

      if (!streamInfo?.playback_url && !streamInfo?.video_url) {
        throw new Error(
          "Bunny Stream upload succeeded but playback URL is missing",
        );
      }

      flushProgress({
        url: streamInfo.playback_url || streamInfo.video_url,
        streamInfo,
        durationSec: null,
        progress: 100,
        status: "creating",
        etaSec: null,
        speedBps: 0,
      });
    } catch (err) {
      const isCanceled =
        err?.name === "CanceledError" ||
        err?.code === "ERR_CANCELED" ||
        /aborted|cancel/i.test(String(err?.message || ""));

      if (isCanceled) {
        flushProgress({
          status: "canceled",
          error: "",
          controller: null,
          etaSec: null,
          speedBps: 0,
        });
        cleanupTracker(id);
        return;
      }

      const msg =
        err?.response?.data?.message ||
        err?.response?.data?.detail ||
        err?.message ||
        "Bunny Stream upload failed";

      flushProgress({
        status: "error",
        error: msg,
        controller: null,
        etaSec: null,
        speedBps: 0,
      });
      cleanupTracker(id);
      return;
    }

    await createVideoWithTimeout(
      id,
      streamInfo,
      entry.title,
      null,
      entry.categoryId,
      visibility,
    );

    cleanupTracker(id);
  }

  async function createVideoWithTimeout(
    id,
    streamInfo,
    title,
    durationSec,
    categoryId,
    visibility,
  ) {
    const streamKey = String(
      streamInfo?.bunny_video_id ||
        streamInfo?.provider_key ||
        streamInfo?.video_url ||
        streamInfo?.playback_url ||
        id,
    );

    // Prevent duplicate DB rows when React re-renders, the modal refreshes, or
    // a TUS upload success callback fires more than once for the same Bunny video.
    if (createLocksRef.current[streamKey]) {
      return;
    }
    createLocksRef.current[streamKey] = true;

    const ctl = new AbortController();
    const to = setTimeout(() => ctl.abort(), CREATE_TIMEOUT_MS);

    try {
      const created = await api.post(
        "/videos",
        {
          title,
          description: "",
          video_url: streamInfo?.video_url || streamInfo?.playback_url,
          playback_url: streamInfo?.playback_url || streamInfo?.video_url,
          embed_url: streamInfo?.embed_url || null,
          // Keep Bunny Stream uploads from saving raw vz-*.b-cdn.net thumbnail URLs.
          // Those URLs may show "Domain suspended or not configured" when opened directly.
          thumbnail_url: null,
          bunny_video_id:
            streamInfo?.bunny_video_id || streamInfo?.provider_key || null,
          bunny_library_id: streamInfo?.bunny_library_id || null,
          provider: streamInfo?.provider || "bunny_stream",
          provider_key:
            streamInfo?.provider_key || streamInfo?.bunny_video_id || null,
          processing_status: streamInfo?.processing_status || "processing",
          category_id: categoryId ?? null,
          visibility: (visibility || "private").toLowerCase(),
          is_premium: true,
          duration_seconds: durationSec ?? undefined,
        },
        { signal: ctl.signal },
      );

      clearTimeout(to);

      const vid = created?.data?.id ?? null;
      const processingStatus = created?.data?.processing_status ?? null;

      patchItem(id, (cur) => {
        if (!cur) return cur;
        return {
          ...cur,
          progress: 100,
          status: "done",
          videoId: vid,
          processingStatus,
          controller: null,
          etaSec: null,
          speedBps: 0,
        };
      });
    } catch (err) {
      clearTimeout(to);
      delete createLocksRef.current[streamKey];

      const msg =
        err?.name === "CanceledError" || err?.code === "ERR_CANCELED"
          ? "Creating the video timed out. Please click Retry."
          : err?.response?.data?.message ||
            err?.message ||
            "Failed to create video";

      patchItem(id, (cur) => {
        if (!cur) return cur;
        return {
          ...cur,
          progress: 100,
          status: "error",
          error: msg,
          controller: null,
          etaSec: null,
          speedBps: 0,
        };
      });
    }
  }
  async function retryCreate(id) {
    const it = items.find((x) => x.id === id);
    if (!it?.streamInfo && !it?.url) return;

    patchItem(id, (cur) => {
      if (!cur) return cur;
      return { ...cur, status: "creating", error: "" };
    });

    await createVideoWithTimeout(
      id,
      it.streamInfo || {
        video_url: it.url,
        playback_url: it.url,
        provider: "bunny_stream",
        processing_status: "processing",
      },
      it.title,
      it.durationSec,
      it.categoryId,
      it.visibility,
    );
  }

  // Poll processing status (queued → processing → ready)
  useEffect(() => {
    if (!open) return;

    const idsToPoll = items
      .filter((i) => i.status === "done" && i.videoId)
      .map((i) => i.videoId);
    if (!idsToPoll.length) return;

    let cancelled = false;

    const tick = async () => {
      try {
        await Promise.all(
          idsToPoll.map(async (vid) => {
            try {
              const res = await api.get(`/videos/${vid}/status`);
              const s = res?.data?.processing_status || null;
              if (!cancelled && s) {
                setItems((prev) => {
                  let changed = false;
                  const next = prev.map((it) => {
                    if (it.videoId === vid && it.processingStatus !== s) {
                      changed = true;
                      return { ...it, processingStatus: s };
                    }
                    return it;
                  });
                  return changed ? next : prev;
                });
              }
            } catch {}
          }),
        );
      } catch {}
    };

    tick();
    const t = setInterval(tick, POLL_MS);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, [open, items]);

  const allFinished = useMemo(() => {
    return (
      items.length > 0 &&
      items.every((i) => ["done", "error", "canceled"].includes(i.status))
    );
  }, [items]);

  const allSucceeded = useMemo(() => {
    return items.length > 0 && items.every((i) => i.status === "done");
  }, [items]);

  const refreshRoute = () => {
    try {
      navigate(0);
    } catch {
      window.location.reload();
    }
  };

  const handleClose = () => {
    onClose?.();
    const shouldRefresh = items.some((i) => i.status === "done");
    if (shouldRefresh) setTimeout(refreshRoute, 0);
  };

  const handleDone = () => {
    try {
      onDone?.(items.filter((i) => i.videoId).map((i) => i.videoId));
    } catch {}
    onClose?.();
    setTimeout(refreshRoute, 0);
  };

  if (!open) return null;

  return (
    <div className="uvm-overlay" onClick={handleClose}>
      <div
        className="uvm-modal"
        role="dialog"
        aria-modal="true"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="uvm-head">
          <h3 className="uvm-title">Upload videos</h3>
          <button
            className="uvm-x"
            aria-label="Close"
            title="Close"
            onClick={handleClose}
          >
            ×
          </button>
        </div>

        {/* Category controls */}
        <div className="uvm-category-section">
          <div className="uvm-category-row">
            <label className="uvm-category-label">
              Category
              <select
                className="uvm-category-select"
                value={selectedCategoryId ?? ""}
                onChange={handleCategoryChange}
                disabled={categoriesLoading}
              >
                <option value="">Select a category</option>
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>
                    {cat.name}
                  </option>
                ))}
              </select>
            </label>

            <label className="uvm-category-label">
              Visibility
              <select
                className="uvm-category-select"
                value={defaultVisibility}
                onChange={(e) => setDefaultVisibility(e.target.value)}
              >
                <option value="private">Private</option>
                <option value="public">Public</option>
              </select>
            </label>

            {categoriesLoading && (
              <div className="uvm-category-hint">Loading categories…</div>
            )}
          </div>

          {categoryInlineError && (
            <div className="uvm-error uvm-error-small">
              {categoryInlineError}
            </div>
          )}

          {/* ✅ Toggle + / - for new category form */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              marginTop: 10,
            }}
          >
            <button
              type="button"
              className="uvm-btn ghost"
              onClick={() => setShowNewCategory((s) => !s)}
              style={{
                width: 38,
                height: 38,
                padding: 0,
                display: "grid",
                placeItems: "center",
                fontSize: 18,
                fontWeight: 900,
                lineHeight: 1,
              }}
              aria-label={
                showNewCategory ? "Hide add category" : "Show add category"
              }
              title={showNewCategory ? "Hide add category" : "Add new category"}
            >
              {showNewCategory ? "−" : "+"}
            </button>

            <div style={{ opacity: 0.85, fontSize: 13 }}>
              {showNewCategory ? "Add a new category" : "Need a new category?"}
            </div>
          </div>

          {showNewCategory && (
            <form
              className="uvm-category-new"
              onSubmit={handleCreateCategory}
              autoComplete="off"
              style={{ marginTop: 10 }}
            >
              <input
                type="text"
                className="uvm-category-input"
                placeholder="New category name"
                value={newCategoryName}
                onChange={(e) => setNewCategoryName(e.target.value)}
              />
              <button
                type="submit"
                className="uvm-btn small"
                disabled={creatingCategory || !newCategoryName.trim()}
              >
                {creatingCategory ? "Adding…" : "Add category"}
              </button>
            </form>
          )}

          {categoriesError && (
            <div className="uvm-error uvm-error-small">{categoriesError}</div>
          )}
        </div>

        {allSucceeded && (
          <div className="uvm-alert success">
            <div className="uvm-alert-icon">✔</div>
            <div className="uvm-message">
              All videos uploaded. Processing will continue in the background.
              You can close this window or upload more.
            </div>
          </div>
        )}

        {items.map((it) => {
          const showRemove = ["queued", "error", "canceled", "done"].includes(
            it.status,
          );

          const statusLabel =
            it.status === "uploading"
              ? "Uploading…"
              : it.status === "creating"
                ? "Creating…"
                : it.status === "done"
                  ? it.processingStatus === "ready"
                    ? "Ready"
                    : it.processingStatus === "processing"
                      ? "Processing…"
                      : it.processingStatus === "queued"
                        ? "Queued for processing…"
                        : "Uploaded"
                  : it.status === "canceled"
                    ? "Canceled"
                    : it.status === "error"
                      ? "Failed"
                      : "Queued";

          const widthPct =
            it.progress || (["creating", "done"].includes(it.status) ? 100 : 0);

          return (
            <div className="uvm-file-row" key={it.id}>
              <div className="uvm-file-main">
                <div className="uvm-file-name">{it.title}</div>
                <div className="uvm-file-sub">
                  {statusLabel} {" • "} {fmtBytes(it.sizeBytes)}
                  {it.status === "uploading" &&
                  it.speedBps > 0 &&
                  it.etaSec != null ? (
                    <>
                      {" • "} ETA {fmtEta(it.etaSec)}
                    </>
                  ) : null}
                </div>
              </div>

              <div className="uvm-file-progress">
                <div
                  className={`uvm-bar ${it.status}`}
                  style={{ width: `${widthPct}%` }}
                />
              </div>

              <div className="uvm-file-actions">
                {it.status === "queued" && (
                  <button
                    className="uvm-btn ghost"
                    onClick={() => removeItem(it.id)}
                  >
                    Remove
                  </button>
                )}

                {it.status === "uploading" && (
                  <button
                    className="uvm-btn ghost"
                    onClick={() => cancelUpload(it.id)}
                  >
                    Cancel
                  </button>
                )}

                {it.status === "error" && it.url && (
                  <>
                    <button
                      className="uvm-btn primary"
                      onClick={() => retryCreate(it.id)}
                    >
                      Retry
                    </button>
                    <button
                      className="uvm-btn ghost"
                      onClick={() => removeItem(it.id)}
                    >
                      Remove
                    </button>
                  </>
                )}

                {it.status === "done" && it.videoId && (
                  <>
                    <button
                      className="uvm-btn primary"
                      onClick={() => navigate(editHrefFor(it.videoId))}
                    >
                      Edit video
                    </button>
                    {showRemove && (
                      <button
                        className="uvm-btn ghost"
                        onClick={() => removeItem(it.id)}
                      >
                        Remove
                      </button>
                    )}
                  </>
                )}

                {it.status === "canceled" && (
                  <button
                    className="uvm-btn ghost"
                    onClick={() => removeItem(it.id)}
                  >
                    Remove
                  </button>
                )}
              </div>

              {it.status === "error" && (
                <div className="uvm-error">{it.error}</div>
              )}
            </div>
          );
        })}

        <div
          className={`uvm-drop ${dragOver ? "drag" : ""} ${
            !categoryIsValid ? "disabled" : ""
          }`}
          onDragOver={(e) => {
            e.preventDefault();
            if (!categoryIsValid) return;
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={(e) => {
            e.preventDefault();
            setDragOver(false);
            if (!categoryIsValid) {
              setCategoryInlineError(
                "Please select or create a category before uploading.",
              );
              return;
            }
            addFiles(e.dataTransfer.files);
          }}
        >
          <CloudIcon />
          <div className="uvm-drop-text">
            {categoryIsValid
              ? "Drag and drop files here"
              : "Select a category to start uploading"}
          </div>

          <div
            style={{
              display: "flex",
              gap: 10,
              flexWrap: "wrap",
              justifyContent: "center",
            }}
          >
            <button
              className="uvm-btn"
              onClick={pickFiles}
              disabled={!categoryIsValid}
            >
              Select files
            </button>

            {allFinished && (
              <button
                className="uvm-btn ghost"
                onClick={pickFiles}
                disabled={!categoryIsValid}
              >
                Upload more
              </button>
            )}
          </div>

          <input
            type="file"
            accept="video/*"
            multiple
            ref={inputRef}
            onChange={(e) => addFiles(e.target.files)}
            style={{ display: "none" }}
          />
        </div>

        <div className="uvm-footer">
          Import from{" "}
          <button
            type="button"
            className="uvm-link"
            onClick={() => navigate("/admin/content/integrations")}
          >
            Google Drive / Dropbox
          </button>{" "}
          (requires connecting your account).
        </div>

        <div className="uvm-bottom">
          <button className="uvm-btn ghost" onClick={handleClose}>
            Close
          </button>
          <button
            className="uvm-btn primary"
            disabled={!allFinished}
            title={!allFinished ? "Wait for uploads to finish" : "Done"}
            onClick={handleDone}
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
}
